#!/usr/bin/env python3
"""Regenerates FourierDSP/Sources/FourierDSP/ColormapTables.swift from
fixtures/dsp.json, so the iOS colormaps are OpenCV's tables byte for byte.

    python3 ios/scripts/gen_colormaps.py
"""
import base64
import json
import pathlib

root = pathlib.Path(__file__).resolve().parents[2]
fixtures = json.loads((root / "fixtures" / "dsp.json").read_text())
out = root / "ios" / "FourierDSP" / "Sources" / "FourierDSP" / "ColormapTables.swift"

lines = [
    "// Generated by ios/scripts/gen_colormaps.py from fixtures/dsp.json. Do not edit.",
    "// 256 RGB triples per map, taken from OpenCV's applyColorMap.",
    "",
    "enum ColormapTables {",
]
for name, rgb in fixtures["colormaps"].items():
    assert len(rgb) == 768
    lines.append(f'    static let {name} = "{base64.b64encode(bytes(rgb)).decode()}"')
lines.append("}")
out.write_text("\n".join(lines) + "\n")
print(f"wrote {out.relative_to(root)}")
